-- Map/Icons.lua: icon name -> texture path and the target -> icon mapping.
-- The pin_*.tga files are generated by the texture script; a missing file only makes the
-- texture invisible in-game, so every lookup degrades to a path instead of erroring.
local _, ns = ...

local M = ns.PQ:GetModule("Icons")   -- an AceAddon module (Core/Const.lua)
ns.Icons = M

local type, pairs, tostring = type, pairs, tostring
local byte, len, sqrt = string.byte, string.len, math.sqrt

local TEXTURE_ROOT = "Interface\\AddOns\\PandaQuest\\Textures\\"

-- Contract name -> file below Textures/. The first block is ns.Const.ICON_KINDS and must stay in sync with it; the second is the dot and its ring added later,
-- which is not part of that older contract. There are no per-kind gathering glyphs:
-- a gathering node is the same dot as an objective spawn, tinted by kind (see KIND_COLORS).
local FILES = {
    available            = "pin_available.tga",
    available_gray       = "pin_available_gray.tga",
    available_repeatable = "pin_available_repeatable.tga",
    complete             = "pin_complete.tga",
    complete_repeatable  = "pin_complete_repeatable.tga",
    slay                 = "pin_slay.tga",
    loot                 = "pin_loot.tga",
    object               = "pin_object.tga",
    talk                 = "pin_talk.tga",
    event                = "pin_event.tga",
    itemuse              = "pin_itemuse.tga",
    explore              = "pin_explore.tga",
    pickup               = "pin_pickup.tga",
    custom               = "pin_custom.tga",
    glow                 = "arrow_glow.tga",
    arrow                = "arrow.tga",
    -- The objective dot and its ring.
    node                 = "node.tga",
    node_outline         = "node_outline.tga",
}
M.FILES = FILES

-- Client textures are shared by the supported Classic branches. Quest glyphs
-- already have a transparent silhouette, so only square item art is cropped.
local QUEST_TEXTURES = {
    available = "AvailableQuestIcon",
    available_gray = "AvailableQuestIcon",
    available_repeatable = "DailyQuestIcon",
    pickup = "AvailableQuestIcon",
    complete = "ActiveQuestIcon",
    complete_repeatable = "DailyActiveQuestIcon",
}
local ITEM_TEXTURES = {
    slay = "Ability_DualWield",
    loot = "INV_Misc_Bag_10",
    object = "INV_Misc_Key_03",
    talk = "INV_Misc_Book_09",
    event = "INV_Misc_Spyglass_03",
    itemuse = "INV_Misc_Bag_10",
    explore = "INV_Misc_Map_01",
    custom = "INV_Misc_Map_01",
}

-- Resolved paths are cached: Pins asks for them once per pin and per redraw.
local pathCache = {}

--- Icons.Get(name) -> texturePath. Unknown names fall back to "custom" so a pin is always drawn.
function M.Get(name)
    if type(name) ~= "string" then name = "custom" end
    local cached = pathCache[name]
    if cached then return cached end
    local quest, item = QUEST_TEXTURES[name], ITEM_TEXTURES[name]
    local path = quest and ("Interface\\GossipFrame\\" .. quest)
        or item and ("Interface\\Icons\\" .. item)
        or FILES[name] and (TEXTURE_ROOT .. FILES[name])
        or M.Get("custom")
    pathCache[name] = path
    return path
end

--- Icons.Exists(name) -> bool. True when the contract knows this icon name.
function M.Exists(name)
    return type(name) == "string" and FILES[name] ~= nil
end

--- Icons.GetRoot() -> "Interface\\AddOns\\PandaQuest\\Textures\\"
function M.GetRoot()
    return TEXTURE_ROOT
end

---------------------------------------------------------------------------
-- Target -> icon
---------------------------------------------------------------------------

-- Fallbacks when Objectives did not stamp target.icon.
local KIND_ICON = {
    TURNIN  = "complete",
    PICKUP  = "available",
    ITEMUSE = "itemuse",
    EXPLORE = "explore",
    CUSTOM  = "custom",
}

local ENTITY_ICON = {
    npc    = "slay",
    object = "object",
    item   = "loot",
    area   = "explore",
}

--- Icons.NameForTarget(target) -> icon name (never nil).
function M.NameForTarget(target)
    if type(target) ~= "table" then return "custom" end
    local name = target.icon
    if type(name) == "string" and FILES[name] then
        return name
    end
    local byKind = KIND_ICON[target.kind]
    if byKind then return byKind end
    return ENTITY_ICON[target.entityType] or "slay"
end

--- Icons.GetForTarget(target) -> texturePath, iconName
function M.GetForTarget(target)
    local name = M.NameForTarget(target)
    return M.Get(name), name
end

---------------------------------------------------------------------------
-- Sizes (profile.map.iconScale / minimapIconScale)
---------------------------------------------------------------------------

local BASE_SIZE = 16               -- world-map pin edge in pixels at scale 1.0
local BASE_MINIMAP_SIZE = 10       -- Smaller than the world map, the owner could not read it
local MIN_SIZE, MAX_SIZE = 4, 64

-- Objective dots are smaller again than the `!`/`?` icons they replaced: those are
-- glyphs that have to stay legible, a dot only has to be visible.
local BASE_NODE_SIZE = 13
local BASE_NODE_MINIMAP_SIZE = 9
local CLUSTER_FACTOR = 1.35        -- pfQuest draws a cluster at 18 px where a node is 14

local function mapProfile()
    local PQ = ns.PQ
    local profile = PQ and PQ.db and PQ.db.profile
    return profile and profile.map
end

--- Icons.GetScale(minimap) -> number. profile.map.iconScale / minimapIconScale, clamped to 0.25..4.
function M.GetScale(minimap)
    local map = mapProfile()
    local scale = map and (minimap and map.minimapIconScale or map.iconScale)
    if type(scale) ~= "number" or scale ~= scale then scale = 1.0 end
    if scale < 0.25 then scale = 0.25 end
    if scale > 4 then scale = 4 end
    return scale
end

--- Icons.GetSize(minimap) -> pixels, honouring profile.map.iconScale.
function M.GetSize(minimap)
    local base = minimap and BASE_MINIMAP_SIZE or BASE_SIZE
    local size = base * M.GetScale(minimap)
    if size < MIN_SIZE then size = MIN_SIZE end
    if size > MAX_SIZE then size = MAX_SIZE end
    return size
end

--- Icons.GetNodeScale() -> number. profile.map.nodeScale, clamped to 0.25..4. Separate from
-- iconScale so a player can shrink the dots without shrinking the `!` and `?` glyphs.
function M.GetNodeScale()
    local map = mapProfile()
    local scale = map and map.nodeScale
    if type(scale) ~= "number" or scale ~= scale then scale = 1.0 end
    if scale < 0.25 then scale = 0.25 end
    if scale > 4 then scale = 4 end
    return scale
end

--- Icons.GetNodeSize(minimap, cluster) -> pixels for an objective dot.
function M.GetNodeSize(minimap, cluster)
    local base = minimap and BASE_NODE_MINIMAP_SIZE or BASE_NODE_SIZE
    local size = base * M.GetScale(minimap) * M.GetNodeScale()
    if cluster then size = size * CLUSTER_FACTOR end
    if size < MIN_SIZE then size = MIN_SIZE end
    if size > MAX_SIZE then size = MAX_SIZE end
    return size
end

M.BASE_SIZE = BASE_SIZE
M.BASE_MINIMAP_SIZE = BASE_MINIMAP_SIZE
M.BASE_NODE_SIZE = BASE_NODE_SIZE
M.BASE_NODE_MINIMAP_SIZE = BASE_NODE_MINIMAP_SIZE
M.CLUSTER_FACTOR = CLUSTER_FACTOR

---------------------------------------------------------------------------
-- Quest colour
---------------------------------------------------------------------------

-- pfQuest's str2rgb (_reference/pfQuest/map.lua:116) ported to Lua 5.1: a stable hash of the quest
-- name folded into 24 bits and split into three bytes. The point is that it needs no palette --
-- every quest gets its own colour, the same colour in every session and for every player, and two
-- dots of the same colour are two spawns of the same quest.
--
-- The intermediate values stay well inside the 2^53 a double represents exactly: `counter` is
-- reduced modulo 4294967279 at the top of each iteration, so the largest product formed is about
-- 2.1e14.
local rgbCache = {}

local function str2rgb(text)
    local counter = 1
    local l = len(text)
    for i = 1, l, 3 do
        counter = (counter * 8161) % 4294967279
            + (byte(text, i) * 16776193)
            + ((byte(text, i + 1) or (l - i + 256)) * 8372226)
            + ((byte(text, i + 2) or (l - i + 256)) * 3932164)
    end
    local hash = (counter % 4294967291) % 16777216
    local r = (hash - (hash % 65536)) / 65536
    local g = ((hash - r * 65536) - ((hash - r * 65536) % 256)) / 256
    local b = hash - r * 65536 - g * 256
    return r / 255, g / 255, b / 255
end

-- Perceived brightness of the hash, and the floor we insist on. A raw str2rgb value is uniform
-- over the whole cube, so roughly a fifth of all quests would land on a colour too dark to see
-- against the world map's terrain. Scaling the darkest ones up keeps the hash deterministic (the
-- correction is a pure function of the colour) while giving every quest a visible dot.
local MIN_LUMA = 0.42

local function lumaOf(r, g, b)
    return sqrt(0.299 * r * r + 0.587 * g * g + 0.114 * b * b)
end

local function brighten(r, g, b)
    local luma = lumaOf(r, g, b)
    if luma >= MIN_LUMA then return r, g, b end
    -- Scaling the three channels keeps the hue, and is the right answer whenever it fits inside
    -- the cube. A colour like (0.05, 0.05, 0.95) does not fit -- scaling it would clamp the blue
    -- and leave the result as dark as it started -- so those blend towards white instead, which
    -- always reaches the floor because white's luma is 1. Twelve bisection steps put the result
    -- within 1/4096 of the floor, and the whole thing is still a pure function of the hash.
    if luma > 0.0001 then
        local k = MIN_LUMA / luma
        if r * k <= 1 and g * k <= 1 and b * k <= 1 then
            return r * k, g * k, b * k
        end
    end
    local lo, hi = 0, 1
    for _ = 1, 12 do
        local t = (lo + hi) / 2
        if lumaOf(r + (1 - r) * t, g + (1 - g) * t, b + (1 - b) * t) < MIN_LUMA then
            lo = t
        else
            hi = t
        end
    end
    return r + (1 - r) * hi, g + (1 - g) * hi, b + (1 - b) * hi
end

--- Icons.QuestColor(text) -> r, g, b (0..1). Deterministic, cached, never nil.
function M.QuestColor(text)
    if type(text) ~= "string" or text == "" then text = "PandaQuest" end
    local cached = rgbCache[text]
    if cached then return cached[1], cached[2], cached[3] end
    local r, g, b = brighten(str2rgb(text))
    rgbCache[text] = { r, g, b }
    return r, g, b
end

---------------------------------------------------------------------------
-- Gathering colour
---------------------------------------------------------------------------

-- One colour per gathering kind, on the same dot and ring as an objective spawn. The owner played
-- with a pickaxe, a sprig, a fish, a chest and a skull on the map and called them "really
-- confusing": at 16 px they were five different pictures competing with the quest dots, and a
-- mining spot is what they wanted to find at a glance - "a small yellow ball". So mining is
-- yellow because they asked for yellow, and the other four are spread round the hue circle far
-- enough from it and from each other to be told apart on a 7 px minimap dot. Every one of them is
-- well above MIN_LUMA, the floor that keeps a quest dot readable on the map's terrain, and the
-- dark ring (node_outline.tga) carries them on snow and sand alike, exactly as it does the quests.
-- A quest's colour is a hash and can land anywhere, so these cannot be kept away from every quest;
-- what keeps the two apart is that a gathering dot is always one of these five.
local KIND_COLORS = {
    mine  = { 1.00, 0.85, 0.10 },       -- yellow
    herb  = { 0.35, 0.90, 0.30 },       -- green
    fish  = { 0.30, 0.70, 1.00 },       -- blue
    chest = { 0.80, 0.50, 1.00 },       -- violet
    rare  = { 1.00, 0.35, 0.30 },       -- red
}
M.KIND_COLORS = KIND_COLORS

--- Icons.KindColor(kind) -> r, g, b. A kind this table does not know gets plain white rather than
-- nil, so a kind added to Nodes/Professions.lua before it is given a colour still draws.
function M.KindColor(kind)
    local color = KIND_COLORS[kind]
    if not color then return 1, 1, 1 end
    return color[1], color[2], color[3]
end

--- Icons.ColorForSpec(spec) -> r, g, b. A gathering node is coloured by its kind. Everything else
-- takes the quest *name*, with the quest id and then the entity name as fallbacks so
-- an unnamed target still gets a stable dot.
function M.ColorForSpec(spec)
    if spec and spec.layer == "profession" then return M.KindColor(spec.kind) end
    local target = spec and spec.targets and spec.targets[1]
    if not target then return M.QuestColor(nil) end
    local text = target.questTitle
    if type(text) ~= "string" or text == "" then
        text = target.questID and ("quest:" .. tostring(target.questID))
            or target.entityName or target.key or nil
    end
    return M.QuestColor(text)
end

---------------------------------------------------------------------------
-- Pin appearance
---------------------------------------------------------------------------

local function cropIcon(texture, square)
    if texture.SetTexCoord then
        local inset = square and 0.08 or 0
        texture:SetTexCoord(inset, 1 - inset, inset, 1 - inset)
    end
end

local function drawTarget(texture, target)
    local path, name = M.GetForTarget(target)
    texture:SetTexture(path)
    cropIcon(texture, ITEM_TEXTURES[name] ~= nil)
    if texture.SetDesaturated then texture:SetDesaturated(name == "available_gray") end
    return name
end

--- Draw a single symbol for a pin, including a group of nearby spawns.
function M.ApplyNode(pin, spec, minimap)
    if not pin or not pin.texture then return nil end
    local texture = pin.texture
    local target = spec and spec.targets and spec.targets[1]
    local gathering = spec and spec.layer == "profession"
    local objective = spec and spec.layer == "objective"
    local size = objective and M.GetNodeSize(minimap, false) or M.GetSize(minimap)
    local compat = ns.MapCompat
    local factor = compat and compat.GetPinScaleFactor and compat.GetPinScaleFactor(pin) or 1
    local frameSize = size * factor
    local resource = gathering and ns.Professions and ns.Professions.GetNodeIcon(spec)
    local square
    if resource then
        texture:SetTexture(resource)
        texture:SetDesaturated(false)
        cropIcon(texture, true)
        square = true
    else
        local name = drawTarget(texture, target)
        square = ITEM_TEXTURES[name] ~= nil
    end
    if pin.mask and square ~= pin.maskApplied then
        if square then texture:AddMaskTexture(pin.mask)
        else texture:RemoveMaskTexture(pin.mask) end
        pin.maskApplied = square
    end
    texture:SetVertexColor(1, 1, 1, 1)
    pin:SetSize(frameSize, frameSize)
    texture:SetSize(frameSize, frameSize)
    return "icon", frameSize
end

--- Applies the icon of `target` (and the configured size) to a texture + its owning frame.
-- Returns the icon name that was used, or nil when there was nothing to draw on.
function M.Apply(texture, target, minimap, frame)
    if not texture or not texture.SetTexture then return nil end
    local name = drawTarget(texture, target)
    local size = M.GetSize(minimap)
    if frame and frame.SetSize then frame:SetSize(size, size) end
    if texture.SetSize then texture:SetSize(size, size) end
    return name
end

function M.OnProfileChanged()
    -- Paths do not depend on the profile, but the cache is cheap to drop and keeps a reloaded
    -- texture set (make_textures.py rerun) from sticking around.
    for k in pairs(pathCache) do pathCache[k] = nil end
end
